    "description": "Вы управляете стихиями, создавая один из следующих эффектов в пределах досягаемости.\n\nВоззвать Воздух. Вы создаёте ветерок, достаточно сильный, чтобы колыхать ткань, поднимать пыль, шевелить листья и закрывать открытые двери и ставни в пределах 5-футового куба. Двери и ставни, которые кто-то или что-то держит открытыми, не будут затронуты.\n\nВоззвать Землю. Вы создаёте тонкую завесу из пыли или песка, покрывающую местность в 5-футовом квадрате, или заставляете одно слово появиться на песке или в грязи вашим почерком.\n\nВоззвать Огонь. Вы создаёте тонкое облако безвредных искр и цветного, ароматного дыма в пределах 5-футового куба. Вы выбираете цвет и запах, а искры могут зажечь свечи, факелы или лампы в этой области. Запах дыма остаётся в течение 1 минуты.\n\nВоззвать Воду. Вы создаёте струю прохладного тумана, которая слегка увлажняет существ и объекты в пределах 5-футового куба. В качестве альтернативы, вы создаёте 1 чашку чистой воды в открытом контейнере или на поверхности, и вода испаряется через 1 минуту.\n\nВаяние Стихии. Вы заставляете грязь, песок, огонь, дым, туман или воду, которые могут поместиться в 1-футовый куб, принять грубую форму (например, существа) на 1 час.",
