    "description": "Вы встраиваете сообщение в объект в пределах дистанции — сообщение, которое произносится, когда выполняется условие активации. Выберите объект, который вы видите и который не носит и не несёт другое существо. Затем произнесите сообщение, которое должно содержать не более 25 слов, хотя его можно произносить в течение 10 минут. Наконец, определите условие, при котором заклинание сработает и сообщение будет передано.\n\nКогда это условие выполняется, на объекте появляется магический рот, который произносит сообщение вашим голосом и на том же уровне громкости, что и вы. Если выбранный вами объект имеет рот или что-то, что на него похоже (например, рот статуи), то магический рот появляется именно там, так что слова кажутся исходящими из рта объекта.\n\nПри наложении этого заклинания вы можете указать, чтобы оно закончилось после передачи сообщения, либо чтобы оно оставалось и повторяло сообщение каждый раз, когда условие выполняется. Условие активации может быть настолько общим или подробным, насколько вам нужно, однако оно должно основываться на визуальных или звуковых условиях, происходящих в пределах 30 футов от объекта. Например, вы можете указать, чтобы рот заговорил, когда любое существо приблизится к объекту на расстояние 30 футов или когда в пределах 30 футов зазвонит серебряный колокольчик.",
