    "description": "Вы пытаетесь создать иллюзию в разуме существа, которое вы видите в пределах дистанции. Цель совершает спасбросок Интеллекта. В случае провала вы создаёте фантомный объект, существо или другое явление, которое не превышает размер 10-футового куба и воспринимается только целью на время действия заклинания. Иллюзия включает звуки, температуру и другие раздражители.\n\nЦель может выполнить действие Изучение, чтобы исследовать фантом с помощью проверки Интеллекта (Анализ) против Сл. спасброска вашего заклинания. Если проверка успешна, цель осознаёт, что фантом является иллюзией, и заклинание заканчивается.\n\nПока цель находится под действием заклинания, она воспринимает фантом как реальный объект и рационализирует любые нелогичные последствия взаимодействия с ним. Например, если цель шагнёт на фантомный мост и переживёт падение, она будет считать, что мост существует, а что-то другое стало причиной падения.\n\nПоражённая цель может даже получить урон от иллюзии, если фантом представляет собой опасное существо или угрозу. В каждый из ваших ходов такой фантом может наносить цели 2к8 урона психической энергией, если она находится в области фантома или в пределах 5 фт. от него. Цель воспринимает урон как соответствующий иллюзии тип.",
