    "description": "Прикосновением вы накладываете иллюзию на согласное существо или предмет, который никто не несёт и не носит. Существо получает эффект «Маскировка», а предмет эффект «Ложная аура», описанные далее. Эффект сохранятся на протяжении всей длительности заклинания. Если вы накладываете заклинание на одну и ту же цель каждый день в течение 30 дней, то иллюзия сохраняется до тех пор, пока не будет рассеяна.\n\nМаскировка (существо). Выберите тип существа, отличный от реального типа цели. Заклинания и другие магические эффекты будут считать цель существом выбранного типа.\n\nЛожная аура (предмет). Вы изменяете восприятие цели заклинаниями и магическими эффектами, которые обнаруживают магические ауры, такими как Обнаружение магии [Detect Magic]. Вы можете сделать так, чтобы немагический предмет казался магическим, чтобы магический предмет казался немагическим, или изменить ауру предмета так, чтобы она принадлежала выбранной вами школе магии.",
