    "description": "Вы активируете один из нижеуказанных эффектов. Пока заклинание действует, вы можете активировать любой из этих эффектов, используя действие магия во время своего хода.\n\nОщущение мыслей. Вы чувствуете присутствие мыслей в радиусе 30 футов от себя, принадлежащих существам, которые знают языки или обладают телепатией. Вы не читаете мысли, но узнаете, что поблизости есть мыслящее существо. Заклинание блокируется 1 футом камня, земли или дерева; 1 дюймом металла или тонким листом свинца.\n\nЧтение мыслей. Выберите 1 существо, которое вы видите в радиусе 30 футов от себя, или 1 существо, которое вы обнаружили с помощью эффектов Ощущение мыслей. Вы узнаете, что сейчас больше всего занимает разум цели прямо сейчас. Если цель не знает языков и не обладает телепатией, то вы ничего не узнаете.\n\nДействием магия в свой следующий ход, вы можете попытаться проникнуть глубже в разум цели. Если вы углубитесь, то цель совершает спасбросок Мудрости. В случае провала вы узнаете её рассуждения, эмоции и что-то важное в её сознании (например, беспокойство, любовь или ненависть). В случае успешного спасброска заклинание заканчивается. В любом случае цель узнает, что вы исследуете её разум, и пока вы не переключите внимание на что-то другое, цель может совершить действие в свой ход, чтобы сделать проверку Интеллекта (Аркана) против Сл. вашего спасброска заклинания, закончив заклинание в случае успеха.",
