    "description": "Вы призываете потустороннее существо, которое появляется в виде верного скакуна в свободном пространстве по вашему выбору в пределах дистанции. Это существо использует статблок Потусторонний скакун [Otherworldly Steed]. Если у вас уже есть скакун, вызванный этим заклинанием, то новый скакун заменяет старого.\n\nСкакун выглядит как крупное, пригодное для езды верховое животное на ваш выбор, такое как лошадь, верблюд, лютый волк или лось. Каждый раз, когда вы накладываете это заклинание, выберите тип существа скакуна: небожитель, фея или исчадие. Это определяет некоторые умения в его статблоке.\n\nБой. Скакун является союзником для вас и ваших союзников. В бою он делит с вами ваш результат инициативы и действует как управляемое верховое животное, пока вы на нем едете (как это определено в правилах о бое верхом). Если у вас есть состояние недееспособный, то скакун действует сразу после вашего хода и действует независимо, сосредотачиваясь на вашей защите.\n\nИсчезновение скакуна. Скакун исчезает, если его хиты падают до 0 или если вы умираете. При исчезновении он оставляет всё, что носил или нёс. Если вы накладываете это заклинание снова, то вы решаете, призываете ли вы того же скакуна, который исчез, или другого.",
