    "description": "Вы окутываете себя духами, которые оставляют за вами след из эктоплазмы до конца вашего хода. Пока вы окутаны, вы можете перемещаться через занятое пространство, как если бы оно было труднопроходимой местностью, и такое перемещение не вызывает провоцированные атаки. Если вы заканчиваете свой ход в таком пространстве, то возвращаетесь в последнее свободное пространство, в котором находились.\n\nПока вы окутаны, каждый раз, когда вы входите в пространство существа, это существо покрывается эктоплазмой до конца вашего следующего хода. Скорость существа, покрытого эктоплазмой, уменьшается на 10 футов, и в начале своего хода оно получает 2к8 урона некротической энергией. Существо может быть покрыто эктоплазмой только один раз за ход.",
    "source": "PHB",
