    "description": "На время действия заклинание увеличивает или уменьшает существо или предмет, который вы видите в пределах дистанции (см. выбранный эффект ниже). Целевой предмет не должен быть ни надет, ни носим. Если цель — нежелающее существо, то оно может совершить спасбросок Телосложения. В случае успешного спасброска заклинание не оказывает никакого эффекта.\n\nВсё, что надето и несётся целью, меняется в размере вместе с ней. Любой предмет, который она уронит, мгновенно возвращается к нормальному размеру. Метательное оружие или боеприпас возвращаются к нормальному размеру сразу после попадания или промаха.\n\nУвеличение. Размер цели увеличивается на одну категорию (от среднего до большого, например). Цель также получает преимущество на проверки Силы и спасброски Силы. Атака увеличенным оружием или безоружным ударом наносят дополнительно 1к4 урона при попадании.\n\nУменьшение. Размер цели уменьшается на 1 категорию (от среднего до маленького, например). Цель также получает помеху на проверки Силы и спасброски Силы. Атака уменьшенным оружием или безоружным ударом наносят на 1к4 меньше урона при попадании (урон не может быть уменьшен ниже 1).",
