    "description": "В рамках накладывания этого заклинания вы должны потратить две Кости Хитов, иначе заклинание автоматически проваливается. Жизненная кровь, текущая внутри существ, раскрывает вам свои тайны. Существа с иммунитетом к состоянию истощённый обладают иммунитетом к этому заклинанию. Пока заклинание не закончится, вы можете определять, связаны ли существа, которых вы видите, биологическим родством. Кроме того, вы знаете, находятся ли хиты существа на максимуме, ниже максимума, на половине или ниже половины.\n\nОдин раз в каждый свой ход, когда вы попадаете по окровавленному существу броском атаки оружием, Безоружным ударом или заклинанием, вы можете заставить цель получить дополнительный урон некротической энергией. Чтобы определить этот урон, бросьте Кости Хитов, потраченные на накладывание этого заклинания.",
