    "duration": "Постоянно",
    "isConcentration": false,
    "isRitual": false,
    "classes": [
      "wizard"
    ],
    "description": "Когда вы накладываете это заклинание, вы выбираете одно немагическое оружие в пределах дистанции. Это оружие становится магическим и получает особое преимущество в зависимости от типа существа, чья кровь использовалась в качестве материального компонента этого заклинания.\n\nПредмет требует настройки, и только существо, настроившееся на это оружие, получает перечисленные преимущества.\n\n• Аберрация. Ваши атаки оружием наносят дополнительно 1к6 урона психической энергией при попадании. Кроме того, вы можете телепатически общаться с любым существом, получившим хотя бы 1 единицу урона от этого оружия за последние 24 часа, при условии, что вы оба находитесь на одном плане существования.\n• Небожитель. Ваши атаки оружием наносят дополнительно 1к6 урона излучением при попадании. Кроме того, бонусным действием вы можете заставить оружие испускать яркий свет в радиусе 30 футов и тусклый свет ещё на 30 футов. Вы можете прекратить этот эффект другим бонусным действием.\n• Дракон. Ваши броски атаки этим оружием наносят критическое попадание при результате 19 или 20 на к20. Кроме того, вы совершаете спасброски, чтобы избежать или окончить состояние испуганный, с преимуществом.\n• Фея. Ваши атаки оружием наносят дополнительно 1к4 урона силовым полем при попадании. Кроме того, один раз за ход, когда вы попадаете этим оружием по существу в пределах 30 футов, вы можете телепортироваться в незанятое пространство, которое видите, в пределах 5 футов от него.\n• Исчадие. Ваши атаки оружием наносят дополнительно 1к6 урона некротической энергией при попадании. Бонусным действием вы можете изменить этот дополнительный урон на урон холодом или огнём.\n\nКогда вы накладываете это заклинание, вы настраиваетесь на магическое оружие. Длительность заклинания сохраняется, пока вы поддерживаете настройку на оружие.\n\nНа протяжении действия заклинания магический предмет подвержен воздействию заклинания Рассеивание магии [Dispel Magic].\n\nЕсли вы поддерживаете настройку на магическое оружие в течение 1 года, зачарование становится постоянным, и это заклинание оканчивается.",
