    "description": "Вы создаёте чернильную пустоту с радиусом 10 футов в видимую точку, которая выше вас в пределах дистанции. Когда вы накладываете это заклинание, из сферы вырывается магическая тьма, заполняющая цилиндр радиусом 10 футов и высотой 40 футов, исходящий от сферы, до начала вашего следующего хода.\n\nЭтот цилиндр является труднопроходимой местностью , и свет (магический или обычный) не может осветить эту область.\n\nКогда тьма появляется, каждое существо в области должно совершить спасбросок Телосложения. При провале существо получает 3к8 урона холодом и становится ослеплённым до конца своего следующего хода. Существо также совершает этот спасбросок , когда впервые за ход входит в область заклинания или заканчивает там свой ход. Существо совершает этот спасбросок не более одного раза за ход.\n\nДо окончания действия заклинания вы можете действием магия переместить сферу горизонтально на расстояние до 20 футов и заставить её снова изливать магическую тьму до начала вашего следующего хода.",
