    "description": "Вы создаёте изображение объекта, существа или другого видимого явления, размером не больше, чем 20-футовый куб. Изображение появляется в выбранной вами точке в пределах дистанции и существует на протяжении всей длительности заклинания. Оно выглядит реальным, включая звуки, запахи и температуру, соответствующие изображаемому предмету, но не может наносить урон или вызывать состояния.\n\nЕсли вы находитесь в пределах дистанции иллюзии, то вы можете использовать действие магия, чтобы переместить изображение в любую другую точку в пределах дистанции. При перемещении изображения вы можете изменять его внешний вид, чтобы его движения казались естественными. Например, если вы создали изображение существа и перемещаете его, то вы можете изменить изображение, чтобы оно казалось идущим. Аналогично, вы можете заставить иллюзию издавать разные звуки в разное время, например, вести разговор.\n\nФизическое взаимодействие с изображением выявляет его как иллюзию, поскольку сквозь него можно проходить. Существо, которое использует действие поиск для изучения изображения, может определить, что это иллюзия, если успешно выполнит проверку Интеллекта (Анализ) против Сл. спасброска вашего заклинания. Если существо разоблачит иллюзию, то оно сможет видеть сквозь изображение, а его другие сенсорные качества станут для этого существа едва заметными.",
    "source": "PHB",
    "higherLevels": "Заклинание действует до развеивания и не требует концентрации, если его наложить с использованием ячейки 4 уровня или выше."
