    "description": "Яркая вспышка вырывается от вас к выбранной вами точке в пределах дистанции, а затем с гулким рёвом разрастается в огненный взрыв. Каждое существо в пределах сферы с радиусом 20 фт., с центром в этой точке, должно совершить спасбросок Ловкости. Существо получает 8к6 урона огнём при неудачном спасброске или половину этого урона при успехе.\n\nЛегковоспламеняющиеся предметы в области, которые никто не носит и не несёт, начинают гореть .",
