    "description": "Выберите груду костей или труп гуманоида среднего или маленького размера в пределах дистанции. Цель становится нежитью: скелетом, если вы выбрали кости, или зомби, если вы выбрали труп (см. приложение Б для статблоков).\n\nВ каждый ваш ход вы можете бонусным действием мысленно приказать существу, созданному этим заклинанием, если оно находится в пределах 60 футов от вас (если вы контролируете несколько существ, то вы можете отдавать один и тот же приказ любому количеству из них одновременно). Вы решаете, какое действие совершит это существо, и куда оно переместится в свой следующий ход, или вы можете отдать общий приказ, например, охранять комнату или коридор. Если вы не отдадите команду, то существо выполняет действие уклонение и перемещается только для того, чтобы избежать вреда. Получив приказ, существо продолжает его выполнять, пока задача не будет завершена.\n\nСущество находится под вашим контролем 24 часа, после чего перестаёт слушаться команд. Для поддержания контроля ещё на 24 часа вы должны наложить это заклинание на него ещё раз до окончания 24-часового периода. Такое наложение заклинания только поддерживает контроль над уже созданными существами, количество которых не может быть больше 4, и не оживляет новых.",
    "source": "PHB",
    "higherLevels": "Вы оживляете или продлеваете контроль над 2 дополнительными существами за каждый уровень ячейки выше 3. Для каждого создаваемого существа требуется отдельная куча костей или труп."
