    "description": "Вы создаёте руну, которая позже высвобождает магический эффект. Вы наносите её на поверхность (например, на стол или участок пола) или внутри объекта, который можно закрыть (например, книга или сундук), чтобы скрыть знак. Руна может покрывать площадь не более 10 футов в диаметре. Если предмет или поверхность переместят более чем на 10 футов от того места, где вы накладываете заклинание, руна сломается, и заклинание окончится, не срабатывая.\n\nРуна почти незаметна и требует успешной проверки Мудрости (Внимательность) против Сл. ваших заклинаний, чтобы заметить её. При нанесении руны вы устанавливаете триггер и выбираете, будет ли это взрывная или заклинательная руна, как описано ниже.\n\nУстановка триггера. Вы решаете, что активирует руну при накладывании заклинания. Руны, написанные на поверхности, обычно срабатывают от касания, вставания на неё, снимания предмета, стоящего на руне, приближения на определённое расстояние, или манипулирования предметом, на котором начертана руна. Для рун, нанесённых внутри объекта, обычные триггеры включают открытие этого объекта или обнаружение руны. Как только руна активирована, заклинание заканчивается.\n\nВы можете уточнить триггер так, чтобы его активировали только существа определённых типов (например, руна может быть настроена для воздействия только на аберрации). Вы также можете установить условия, при которых существа не активируют руну, например, если они произносят определённый пароль.\n\nВзрывная руна. Когда триггер срабатывает, руна извергает магическую энергию в 20-футовой сфере с центром на руне. Каждое существо в области должно совершить спасбросок Ловкости. Существо получает 5к8 урона кислотой, холодом, огнём, электричеством или звуком (на ваш выбор при создании руны) при провале или половину этого урона при успехе.\n\nЗаклинательная руна. Вы можете хранить подготовленное заклинание 3 уровня или ниже в руне, накладывая его как часть создания руны. Заклинание должно нацеливаться на одно существо или область. Заклинание, сохранённое таким образом, не имеет немедленного эффекта при наложении.\n\nКогда знак активируется, сохранённое заклинание вступает в действие. Если у заклинания есть цель, то оно нацеливается на существо, активировавшее знак. Если заклинание воздействует на область, то эта область с центром на этом существе. Если заклинание призывает враждебных существ или создаёт вредные объекты или ловушки, то они появляются как можно ближе к нарушителю и атакуют его. Если заклинание требует концентрации, то оно длится до конца своего полного срока.",
    "source": "PHB",
    "higherLevels": "Урон взрывной руны увеличивается на 1к8 за каждый уровень ячейки выше 3. Если вы создаёте заклинательную руну, то вы можете хранить любое заклинание до уровня ячейки, использованной для заклинания Охранная руна ."
