    "description": "Существо, которого вы касаетесь, превращается в бешеного монстра, переполненного первобытной яростью. У цели вырастает густая шерсть, а её рот вытягивается в клыкастую пасть. Она получает 20 временных хитов.\n\nПока существо преобразовано, на него действуют следующие эффекты:\n\n• Его КД становится равным 17, если до этого он был ниже.\n• Оно получает бонус +5 к броскам урона атаками, основанными на Силе.\n• Оно может совершать атаку Укус бонусным действием. Укус наносит 1к6 + модификатор Силы рубящего урона.\n• Оно получает иммунитет к состоянию испуганный.\n• Оно не может накладывать заклинания или поддерживать концентрацию.\n• В начале каждого своего хода оно должно преуспеть в спасброске Мудрости Сл. 10, иначе потеряет контроль до окончания действия заклинания. Существо, потерявшее контроль, обязано в каждый свой ход совершать действие Атака, используя рукопашные атаки против ближайшего существа. Если в пределах досягаемости никого нет, существо обязано использовать своё перемещение и, если необходимо, действие рывок, чтобы приблизиться к ближайшему существу.",
    "source": "PHB"
