    "description": "Вы призываете духа бездны. Он проявляется в незанятом пространстве, которое вы видите в пределах дистанции. Этот материальный облик использует блок характеристик Дух морского змея [Sea Serpent Spirit]. Когда вы накладываете это заклинание, выберите отвратительную особенность: Огромная пасть, Светящийся фонарь или Чешуйчатые крылья. Существо напоминает чудовищное морское создание с выбранной отвратительной особенностью, определяющей одну из черт в его блоке характеристик. Существо исчезает, когда его хиты опускаются до 0 или когда действие заклинания заканчивается.\n\nСущество является союзником вам и вашим союзникам. В бою существо использует вашу инициативу, но совершает свой ход сразу после вас. Оно подчиняется вашим словесным командам (не требует действия с вашей стороны). Если вы не отдаёте команд, оно совершает действие уклонение и использует своё перемещение, чтобы избегать опасности.",
