    "isRitual": false,
    "classes": [],
    "description": "Это заклинание проклинает существо нарциссической надменностью.\n\nЦель должна совершить спасбросок Интеллекта.\n\nУспешный спасбросок. При успехе цель получает 2к10 урона психической энергией и осознаёт, что стала целью проклятия.\n\nНачальный эффект. При провале цель получает 4к10 урона психической энергией, получает состояние ослеплённый на 1 минуту и оказывается проклята.\n\nСрабатывающее событие. В следующий раз, когда цель услышит произнесённое своё имя, голос говорящего покажется ей насмешливым независимо от его настоящего тона, и проклятие перейдёт к стадии 1.\n\nСтадия 1. Проклятому существу повсюду слышатся скрытые оскорбления, и оно убеждено, что все завидуют его гениальности и талантам.\n\nСтадия 2. Проклятое существо чувствует беспокойство, если не занято активным достижением какой-либо цели. Существо не получает никаких преимуществ от своих коротких отдыхов.\n\nСтадия 3. Проклятое существо убеждено, что все участвуют в заговоре с целью привести его к гибели. Каждый раз, когда оно проваливает Тест к20, оно совершает следующую Тест к20 с помехой.\n\nКульминация. Проклятое существо превращается в уродливую искривлённую фигуру и становится Пожирателем разума.",
