    "description": "Вы наделяете подобием жизни труп по вашему выбору в пределах дистанции, позволяя ему отвечать на ваши вопросы. Труп должен иметь рот, и заклинание не сработает, если существо было нежитью на момент смерти. Заклинание также не сработает, если труп уже был целью этого заклинания в последние 10 дней.\n\nДо окончания действия заклинания вы можете задать трупу до 5 вопросов. Труп знает только то, что знал при жизни, включая языки, которые он знал. Ответы обычно краткие, загадочные или повторяющиеся. Труп не обязан давать правдивый ответ, если вы проявляете к нему враждебность или он распознает вас как врага. Это заклинание не возвращает душу в тело существа, а только оживляет дух. Таким образом, труп не может узнать новую информацию, не понимает ничего, что произошло после его смерти, и не может строить предположения о будущих событиях.",
