    "description": "Это заклинание направляет жизненную силу в растения. Время накладывания, которое вы используете, определяет, будет ли у заклинания эффект разрастание или удобрение, описанные ниже.\n\nРазрастание. Выберите точку в пределах дистанции. Все обычные растения в сфере радиусом 100 футов, с центром в этой точке, становятся густыми и заросшими. Существо, перемещающееся через эту область, должно тратить 4 фута движения за каждый 1 фут, который оно проходит. Вы можете исключить одну или несколько областей любого размера в пределах зоны действия заклинания из-под его влияния.\n\nУдобрение. Все растения в радиусе полумили, с центром в точке в пределах дистанции, удобряются на 365 дней. Растения дают вдвое больше урожая пищи. Они могут получить пользу от одного заклинания Рост растений в год.",
    "source": "PHB"
