    "description": "Вы входите в каменный объект или поверхность, достаточно большую, чтобы полностью вместить ваше тело, и сливаетесь с камнем на время действия заклинания вместе со своим снаряжением. Чтобы это сделать, вы должны коснуться камня. Ваше присутствие абсолютно незаметно и без помощи магии обнаружить вас невозможно.\n\nПока вы слиты с камнем, вы не видите, что происходит снаружи и любые проверки Внимательности (Мудрость), чтобы услышать звуки снаружи, выполняются с помехой. Вы остаётесь в курсе течения времени и можете накладывать заклинания на себя, будучи слиты с камнем. Вы можете использовать 5 футов перемещения, чтобы покинуть камень в том месте, где вошли, что завершает действие заклинания. В противном случае вы не можете двигаться.\n\nНезначительное физическое повреждение камня не причиняет вам вреда, но его частичное разрушение или изменение формы (до такой степени, что вы больше не помещаетесь в нём) изгоняет вас и наносит 6к6 урона силовым полем. Полное разрушение камня (или его преобразование в другое вещество) изгоняет вас и наносит 50 урона силовым полем. Если вас изгнали, то вы перемещаетесь в ближайшее незанятое пространство к тому месту, где вы вошли, и оказываетесь в состоянии лежащий ничком.",
