    "description": "Когда вы накладываете это заклинание, выберите один из следующих эффектов, определяющих тип урона заклинания:\n\n• Воздух. Тип урона — урон звуком. Каждое существо, провалившее спасбросок, отталкивается на 10 футов от вас.\n• Холодное пламя. Тип урона — урон холодом. Каждое существо, провалившее спасбросок, получает состояние испуганный до начала вашего следующего хода.\n• Земля. Тип урона — дробящий урон. Скорость каждого существа, провалившего спасбросок, уменьшается до 0 до конца его следующего хода.\n• Огонь. Тип урона — урон огнём. Каждое существо, провалившее спасбросок, охватывается пламенем и получает 2к6 урона огнём в конце своего следующего хода. Действием существо может потушить пламя на себе, получив состояние лежащий ничком и катаясь по земле. Пламя также гаснет, если его залить, погрузить в воду или перекрыть доступ воздуха.\n• Вода. Тип урона — урон кислотой. Каждое существо, провалившее спасбросок, получает состояние лежащий ничком.\n\nКаждое существо в 30-футовом конусе разрушительной стихийной энергии должно совершить спасбросок Ловкости. При провале цель получает 5к6 урона выбранного типа. При успехе цель получает только половину этого урона.",
