    "range": "60 футов",
    "components": "В, С",
    "materialDesc": "",
    "duration": "Концентрация, до 1 минуты",
    "isConcentration": true,
    "isRitual": false,
    "classes": [
      "wizard",
      "sorcerer",
      "rogue",
      "fighter"
    ],
    "description": "Вы создаёте столб чаропламени в цилиндре радиусом 20 фт. и высотой 20 фт., центр которого находится в точке в пределах дистанции. Область цилиндра наполнена ярким светом , и каждое существо в ней при появлении совершает спасбросок Телосложения. При провале существо получает 4к10 урона излучением, а при успехе — половину этого урона.\n\nСущество также совершает этот спасбросок, когда впервые входит в область заклинания в свой ход или заканчивает его там. Существо совершает этот спасбросок только один раз за ход.\n\nКроме того, всякий раз, когда существо в пределах цилиндра накладывает заклинание , оно должно совершить спасбросок Телосложения. При провале заклинание рассеивается без эффекта, а использованное для него действие , бонусное действие или реакция теряется. Если это заклинание было наложено с использованием ячейки заклинаний, эта ячейка не расходуется.\n\nКогда вы накладываете это заклинание, вы можете указать существ, на которых оно не действует.\n\nНаложение как заклинания круга. В дополнение к обычным компонентам вы должны предоставить особый компонент — голубой звёздный сапфир стоимостью не менее 25 000 зм, который расходуется заклинанием. При этом дальность увеличивается до 1 мили, и концентрация не требуется. Каждый вторичный заклинатель должен потратить ячейку заклинаний 3-го уровня или выше, иначе заклинание не срабатывает.\n\nВлияние количества вторичных заклинателей. Количество вторичных заклинателей определяет область действия и длительность заклинания, как показано в таблице ниже:\n\n<table class=\"card-table\"><thead><tr><th style=\"text-align: center;\">Вторичных заклинателей</th><th style=\"text-align: left;\">Область действия</th><th style=\"text-align: left;\">Длительность</th></tr></thead><tbody><tr><td style=\"text-align: center;\">1–3</td><td style=\"text-align: left;\">Цилиндр радиусом 40 фт. и высотой 40 фт.</td><td style=\"text-align: left;\">1 час</td></tr><tr><td style=\"text-align: center;\">4–6</td><td style=\"text-align: left;\">Цилиндр радиусом 60 фт. и высотой 60 фт.</td><td style=\"text-align: left;\">8 часов</td></tr><tr><td style=\"text-align: center;\">7+</td><td style=\"text-align: left;\">Цилиндр радиусом 100 фт. и высотой 100 фт.</td><td style=\"text-align: left;\">24 часа</td></tr></tbody></table>\n\nЗаклинание прекращает действие досрочно, если любой из заклинателей, участвовавших в наложении, примет участие в другом наложении заклинания «Буря чаропламени» как заклинания круга.",
    "source": "PHB",
    "higherLevels": "Урон увеличивается на 1к10 за каждый уровень ячейки заклинаний выше 4-го."
