    "description": "Вы заглядываете в кошмары существа, которое видите в пределах дистанции, и создаёте иллюзию его глубочайших страхов, видимую только этому существу. Цель совершает спасбросок Мудрости. В случае провала цель получает 4к10 урона психической энергией и помеху на проверки характеристик и броски атаки на всю длительность заклинания. В случае успешного спасброска цель получает половину этого урона и заклинание прекращается.\n\nНа протяжении действия заклинания цель совершает спасбросок Мудрости в конце каждого своего хода. В случае провала она вновь получает урон психической энергией. В случае успеха заклинание прекращается.",
