    "classes": [
      "bard",
      "cleric",
      "warlock"
    ],
    "description": "Вы создаёте сферу чернильного тумана радиусом 20 фт. в пределах дистанции. Этот туман является магической тьмой и существует всё время действия заклинания, либо до тех пор, пока сильный ветер (например, созданный заклинанием Порыв ветра [Gust of Wind] ) не рассеет его, прекращая действие заклинания.\n\nКаждое существо , находящееся в сфере при её появлении, совершает спасбросок Мудрости. При провале существо получает 5к6 урона психической энергией и вычитает 1к6 из всех своих спасбросков до конца своего следующего хода. При успешном спасброске существо получает только половину урона.\n\nСущество также совершает этот спасбросок, когда сфера перемещается в его пространство, когда оно входит в неё или заканчивает свой ход внутри. Существо совершает этот спасбросок только один раз за ход.\n\nВ начале каждого вашего хода сфера перемещается на 10 фт. от вас.\n\nНаложение как заклинания круга. Чтобы наложить это заклинание как заклинание круга, требуется как минимум пять вторичных заклинателей. В дополнение к обычным компонентам, вы должны предоставить особый компонент — нить из трёх чёрных жемчужин из Пандемониума, который заклинание поглощает.\n\nПри таком наложении дальность увеличивается до 1 мили, а длительность становится «пока не рассеяно» (концентрация не требуется). Заклинание прекращается досрочно, если любой из заклинателей, участвовавших в этом наложении, примет участие в другом наложении заклинания «Роковой прилив» как заклинания круга.\n\nПри наложении каждый вторичный заклинатель должен потратить ячейку заклинаний 3-го уровня или выше, иначе заклинание не срабатывает.",
    "source": "PHB"
