    "description": "Каждое существо в 10-футовой сфере с центром в точке, выбранной вами в пределах дистанции, должно успешно совершить спасбросок Мудрости, иначе оно не сможет совершать бонусные действия или реакции и должно бросить 1к10 в начале каждого своего хода, чтобы определить своё поведение на этот ход, используя таблицу ниже.\n\n<table class=\"card-table\"><thead><tr><th style=\"width: 14%; text-align: center;\"><strong>1к10</strong></th><th style=\"text-align: left;\">Поведение на ход</th></tr></thead><tbody><tr><td style=\"text-align: center;\">1</td><td style=\"text-align: left;\">Цель не совершает действий и использует всё своё перемещение, чтобы двигаться. Бросьте <strong>1к4</strong> , чтобы определить направление: 1 — север, 2 — восток, 3 — юг, 4 — запад.</td></tr><tr><td style=\"text-align: center;\">2–6</td><td style=\"text-align: left;\">Цель не двигается и не совершает действий.</td></tr><tr><td style=\"text-align: center;\">7–8</td><td style=\"text-align: left;\">Цель не двигается и совершает действие <em>Атака</em> , чтобы выполнить одну рукопашную атаку против случайного существа в пределах досягаемости. Если в пределах досягаемости никого нет, цель не совершает действий.</td></tr><tr><td style=\"text-align: center;\">9–10</td><td style=\"text-align: left;\">Цель выбирает своё поведение самостоятельно.</td></tr></tbody></table>\n\nВ конце каждого своего хода поражённая цель повторяет спасбросок, оканчивая действие эффекта на себе при успехе.",
