    "description": "В рамках накладывания этого заклинания вы должны потратить четыре кости хитов, иначе заклинание автоматически провалится. Совершите бросок рукопашной атаки заклинанием против существа в пределах 5 футов, используя материальный компонент этого заклинания.\n\nПри попадании бросьте кости хитов, потраченные на накладывание заклинания, и добавьте 4к8. Вы наносите урон некротической энергией, равный сумме выпавших результатов.\n\nЕсли этот урон уменьшает количество хитов существа до 0, оно немедленно умирает, а вы получаете одно из следующих тёмных благословений на ваш выбор.\n\nКогда вы получаете урон излучением, пока на вас действует тёмное благословение, вы получаете дополнительный 1к4 урона излучением.\n\n• Неуязвимый. Вы совершаете все спасброски с преимуществом.\n• Несокрушимый. Ваш размер увеличивается на одну категорию (например, со Среднего до Большого), вы получаете количество временных хитов, равное вашему модификатору Телосложения (минимум 1), в начале каждого своего хода, а ваши атаки оружием наносят дополнительный 1к4 урона.\n• Безошибочный. Ваш бонус мастерства увеличивается на 2.\n\nВаше тёмное благословение оканчивается через 10 минут или когда количество ваших хитов уменьшается до 0, в зависимости от того, что произойдёт раньше.",
    "source": "PHB",
    "higherLevels": "Начальный урон увеличивается на 1к8 за каждый уровень ячейки заклинаний выше 4."
