    "description": "Выберите несколько трупов в пределах дистанции. Вы можете оживить из этих трупов до пяти существ с типом нежить с ПО 2 или ниже. В каждый свой ход вы можете бонусным действием мысленно приказать любому существу, созданному этим заклинанием, если оно находится в пределах 120 футов от вас (если вы контролируете несколько существ, вы можете отдавать приказ любому количеству из них одновременно, отдавая всем одинаковый приказ). Вы решаете, какое действие существо совершит и куда переместится в свой следующий ход, либо можете отдать общий приказ, например охранять определённую комнату или коридор. Если вы не отдаёте приказов, существо защищается только от враждебных существ. Получив приказ, существо продолжает следовать ему, пока задача не будет выполнена. Существо находится под вашим контролем 24 часа, после чего перестаёт подчиняться вашим приказам.\n\nЧтобы сохранить контроль над существом ещё на 24 часа, вы должны снова наложить это заклинание на существо до окончания текущего периода в 24 часа. Такое использование заклинания восстанавливает ваш контроль максимум над четырьмя существами, которых вы оживили этим заклинанием, вместо создания новых существ. Кроме того, накладывание заклинания таким образом не требует материальных компонентов со стоимостью в зм.",
