    "description": "Вы создаёте руку большого размера из мерцающей магической энергии в свободном пространстве, которое вы видите в пределах дистанции. Рука существует на протяжении длительности заклинания и двигается по вашему приказу, имитируя движения вашей собственной руки.\n\nРука — это объект с КД 20 и Хитами, равными вашему максимальному количеству Хитов. Если хиты руки опускается до 0, заклинание заканчивается. Рука не занимает пространство, в котором находится.\n\nКогда вы накладываете заклинание и бонусным действием на ваших последующих ходах, вы можете переместить руку на расстояние до 60 футов и вызвать одно из следующих действий:\n\n• Сжатый кулак. Рука наносит удар по цели в пределах 5 футов от неё. Совершите рукопашную атаку заклинанием. При попадании цель получает 5к8 урона силовым полем.\n• Могучая длань. Рука пытается толкнуть существо огромного или меньшего размера в пределах 5 футов от неё. Цель должна преуспеть в спасброске Силы, иначе рука толкает её на 5 футов плюс количество футов, равное модификатору вашей заклинательной характеристики, умноженному на 5. Рука движется вместе с целью, оставаясь в пределах 5 футов от неё.\n• Сжимающая длань. Рука пытается схватить существо огромного или меньшего размера в пределах 5 футов от неё. Цель должна преуспеть в спасброске Ловкости, иначе цель получает состояние схваченный, со Сл. освобождения, равной Сл. спасброска ваших заклинаний. Пока рука держит цель, вы можете бонусным действием заставить руку сжать её, нанося дробящий урон цели в размере 4к6 плюс ваш модификатор заклинательной характеристики.\n• Преграждающая длань. Рука предоставляет вам укрытие на половину от атак и других эффектов, которые исходят из её пространства или проходят через него. Кроме того, её пространство считается труднопроходимой местностью для ваших врагов.",
