    "description": "Вы пытаетесь изменить воспоминания другого существа. 1 существо, которое вы видите в пределах дистанции, совершает спасбросок Мудрости. Если вы сражаетесь с существом, то оно совершает этот спасбросок с преимуществом. В случае провала цель получает состояние очарованный на время действия заклинания. Пока существо очаровано таким образом, то оно также получает состояние недееспособный и не осознает окружающую обстановку, хотя может вас слышать. Если цель получает любой урон или становится целью другого заклинания, то это заклинание заканчивается и воспоминания не изменяются.\n\nПока это очарование действует, вы можете изменить воспоминания цели об одном событии, которое произошло в течение последних 24 часов и длилось не более 10 минут. Вы можете полностью стереть память об этом событии, позволить цели вспомнить всё с потрясающей точностью, изменить детали этого события или создать новое воспоминание.\n\nВы должны произносить цели описания, как её воспоминания изменяются, и она должна понимать ваш язык, чтобы измененные воспоминания укоренились. Её разум заполняет любые пробелы в деталях вашего описания. Если заклинание заканчивается до того, как вы завершите описание измененных воспоминаний, то память существа не изменяется. В противном случае измененные воспоминания закрепляются, когда заклинание заканчивается.\n\nИзменённая память не обязательно влияет на поведение существа, особенно если воспоминание противоречит его естественным склонностям, мировоззрению или убеждениям. Нелогичная изменённая память, такая как ложное воспоминание о том, как существо наслаждалось плаванием в кислоте, отвергается как дурной сон. Мастер может решить, что изменённая память слишком бессмысленна, чтобы повлиять на существо.\n\nЗаклинания Снятие проклятья [Remove Curse] или Высшее восстановление [Greater Restoration], наложенные на цель, восстанавливают истинную память существа.",
    "source": "PHB",
    "higherLevels": "Вы можете изменить воспоминания цели о событии, которое произошло до 7 дней назад (ячейка 6 уровня), 30 дней назад (ячейка 7 уровня), 365 дней назад (ячейка 8 уровня) или в любое время в прошлом существа (ячейка 9 уровня)."
