    "description": "Вы отдаёте вербальный приказ существу, которое видите в пределах дистанции, приказывая ему выполнить некую услугу или воздержаться от действия или курса действий, по вашему выбору. Цель должна преуспеть в спасброске Мудрости, иначе она получает состояние очарованный на время действия заклинания. Цель автоматически преуспевает, если не понимает ваш приказ.\n\nПока существо очаровано, оно получает 5к10 урона психической энергией, если действует прямо противоположно вашему приказу. Этот урон наносится не более 1 раза в день.\n\nВы можете отдать любой приказ, кроме тех, которые приведут к неминуемой смерти. Если вы отдаёте самоубийственный приказ, то заклинание заканчивается.\n\nЗаклинания Снятие проклятья [Remove Curse], Высшее восстановление [Greater Restoration] или Желание [Wish] прекращают действие этого заклинания.",
