    "description": "По вашему приказу оживают предметы. Выберите несколько немагических объектов в пределах дистанции, которые никто не несёт и не носит, которые не прикреплены к поверхности и не громадные. Максимальное количество объектов равно модификатору вашей заклинательной характеристики. Для этого количества средний или меньший объект считается за 1, большой объект считается за 2, а огромный объект считается за 3.\n\nВсе цели оживают, у них вырастают ноги, и они становятся конструкциями, которые используют статблок Оживлённый предмет [Animated Object]. Эти существа находятся под вашим контролем, пока это заклинание активно или пока их хиты не уменьшатся до 0. Каждое существо, которое вы оживили этим заклинанием, является союзником для вас и ваших союзников. В бою оно разделяет вашу инициативу и совершает свой ход сразу после вас.\n\nПока это заклинание активно, вы можете бонусным действием мысленно отдать приказ существу, которое оживили этим заклинанием, если оно находится в пределах 500 футов от вас (если вы контролируете несколько существ, то вы можете отдавать один и тот же приказ любому количеству из них одновременно). Если вы не отдадите команду, то существо будет использовать действие уклонение и двигаться только чтобы избежать вреда. Когда хиты существа опускаются до 0, оно возвращается в форму объекта, и оставшийся урон переносится на эту форму.",
