    "description": "Вы пытаетесь обязать небожителя, элементаля, фею или исчадие служить вам. Существо должно находиться в пределах дистанции на протяжении всего накладывания заклинания. Как правило, существо сначала призывается в центр заклинания Магический круг [Magic Circle] с обратным направлением, чтобы удержать цель, пока это заклинание накладывается. По завершении накладывания цель должна совершить спасбросок Харизмы или быть обязанной вам служить на время длительности заклинания. Если существо было призвано или создано другим заклинанием, то длительность другого заклинания продлевается до длительности этого заклинания.\n\nОбязанное существо должно выполнять ваши команды в меру своих возможностей. Вы можете приказать существу сопровождать вас в приключении, охранять место или доставить сообщение. Если существо враждебно, то оно будет стремиться извратить ваши команды, чтобы достичь своих целей. Если существо выполнит ваши команды до окончания заклинания, то оно вернется к вам, чтобы сообщить об этом, если вы находитесь на одном плане бытия. Если вы находитесь на другом плане, то оно возвращается на место, где вы его связали, и остается там до окончания действия заклинания.",
