    "description": "Вы направляете ленты негативной энергии в одно существо , которое видите в пределах дистанции. Если цель не является нежитью, она совершает спасбросок Телосложения, получая 3к10 + 25 урона некротической энергией при провале или половину этого урона при успехе. Гуманоид, убитый этим заклинанием, восстаёт в начале вашего следующего хода в виде зомби , который в течение 24 часов выполняет ваши устные приказы, после чего действует согласно своей природе.\n\nЕсли цель является нежитью, она получает 3к10 временных хитов .",
