    "description": "Вы придаёте иллюзорную внешность каждому существу по вашему выбору, которое вы видите в пределах дистанции. Несогласная цель может совершить спасбросок Харизмы и в случае успеха она не подвергается воздействию этого заклинания.\n\nВы можете придать одну и ту же внешность или разные внешности целям. Заклинание может изменить внешний вид тел и снаряжения целей. Вы можете сделать так, чтобы каждое существо казалось на 1 фут ниже или выше, а также выглядело тяжелее или легче. Новая внешность цели должна сохранять ту же базовую структуру конечностей, что и у цели, но степень иллюзии в остальном зависит от вас. Заклинание длится в течение всего времени действия.\n\nИзменения, произведенные этим заклинанием, не выдерживают проверку физическим исследованием. Например, если вы используете это заклинание, чтобы добавить шляпу к своему наряду, то предметы будут проходить сквозь шляпу, и любой, кто её коснется, не почувствует ничего.\n\nСущество, которое совершает действие изучение для анализа цели, может совершить проверку Интеллекта (Анализ ) против Сл. спасброска вашего заклинания. В случае успеха оно осознает, что цель замаскирована.",
