    "classes": [],
    "description": "Это заклинание проклинает существо смертельно неудачливой судьбой. Цель должна совершить спасбросок Ловкости.\n\nУспешный спасбросок. При успехе цель получает 3к10 урона звуком и осознаёт, что стала целью проклятия. Кроме того, существо совершает первый Тест к20 в течение следующей 1 минуты с помехой.\n\nНачальный эффект. При провале существо получает 7к10 урона звуком и становится проклятым.\n\nСрабатывающее событие. В следующий раз, когда цель проходит через дверной проём, она ушибает палец ноги или ударяется головой, и проклятие переходит к стадии 1.\n\nСтадия 1. Проклятое существо становится жертвой мелких неудобств и невезения. Магазины, которые оно хочет посетить, закрываются прямо перед его приходом, а его снаряжение ломается в самый неподходящий момент.\n\nСтадия 2. Проклятое существо становится маяком неудачи, и безобидные неприятности становятся всё более опасными. Предметы словно постоянно оказываются у него на пути.\n\nКроме того, проклятое существо совершает проверки характеристик и спасброски Ловкости с помехой.\n\nСтадия 3. Проклятое существо становится опасно подвержено несчастным случаям, поскольку даже простейшие действия приводят к непредвиденным смертельным последствиям.\n\nПроклятое существо совершает проверки инициативы с помехой, его скорость уменьшается до 10 футов, и оно получает состояние лежащий ничком, если промахивается броском атаки.\n\nКульминация. Проклятое существо превращается в уродливую искривлённую фигуру и становится Вестником бедствий.",
