    "classes": [],
    "description": "Это заклинание проклинает существо горькой и саморазрушительной жадностью. Цель должна совершить спасбросок Мудрости.\n\nУспешный спасбросок. При успехе цель получает 4к10 урона холодом и осознаёт, что стала целью проклятия.\n\nНачальный эффект. При провале цель получает 6к10 урона холодом, а её скорость уменьшается до 0 на 1 минуту. В конце каждого своего хода скорость цели увеличивается на 5 футов, пока не достигнет своего максимального значения.\n\nСрабатывающее событие. В следующий раз, когда цель завершает короткий или продолжительный отдых, она замечает, что потеряла ценную вещь, и проклятие переходит к стадии 1.\n\nСтадия 1. Проклятое существо испытывает непреодолимое желание воровать безделушки.\n\nСтадия 2. Проклятое существо находит тайное место, где начинает прятать украденные безделушки, и испытывает тревогу, если покидает это место надолго. Существо совершает проверки характеристик и спасброски Мудрости с помехой.\n\nСтадия 3. Проклятое существо стремится превратить своё скопище безделушек в лабиринт из имущества и сокровищ. Существо желает оставаться в этом логове. Существо не может совершать реакции.\n\nКульминация. Проклятое существо превращается в уродливую искривлённую фигуру и становится Паразитической Мерзостью.",
