    "description": "Вы касаетесь мёртвого гуманоида или его части. Если существо мертво не более 10 дней, то заклинание создаёт для него новое тело и призывает душу войти в это тело. Бросьте 1к10 и воспользуйтесь таблицей ниже, чтобы определить вид тела, или Мастер выбирает другой доступный вид.\n\n<table class=\"card-table\"><thead><tr><th style=\"width: 14%; text-align: center;\">1к10</th><th style=\"text-align: left;\">Вид</th></tr></thead><tbody><tr><td style=\"text-align: center;\">1</td><td style=\"text-align: left;\">Аасимар</td></tr><tr><td style=\"text-align: center;\">2</td><td style=\"text-align: left;\">Драконорождённый</td></tr><tr><td style=\"text-align: center;\">3</td><td style=\"text-align: left;\">Дварф</td></tr><tr><td style=\"text-align: center;\">4</td><td style=\"text-align: left;\">Эльф</td></tr><tr><td style=\"text-align: center;\">5</td><td style=\"text-align: left;\">Гном</td></tr><tr><td style=\"text-align: center;\">6</td><td style=\"text-align: left;\">Голиаф</td></tr><tr><td style=\"text-align: center;\">7</td><td style=\"text-align: left;\">Полурослик</td></tr><tr><td style=\"text-align: center;\">8</td><td style=\"text-align: left;\">Человек</td></tr><tr><td style=\"text-align: center;\">9</td><td style=\"text-align: left;\">Орк</td></tr><tr><td style=\"text-align: center;\">10</td><td style=\"text-align: left;\">Тифлинг</td></tr></tbody></table>\n\nПерерождённое существо делает любые выборы, которые предлагает описание его вида, и помнит свою прежнюю жизнь. Оно сохраняет способности, которые имело в своей первоначальной форме, за исключением того, что оно теряет особенности своего предыдущего вида и приобретает особенности нового.",
