    "description": "Вы вызываете всплеск психической энергии в точке в пределах дистанции. Каждое существо в 20-футовой сфере с центром в этой точке должно совершить спасбросок Интеллекта. При провале оно получает 8к6 урона психической энергией, при успехе половину этого урона.\n\nПри провале цели также на 1 минуту окутываются запутанными мыслями. В это время они вычитают 1к6 из всех своих бросков атаки и проверок характеристик, а также спасбросков Телосложения для поддержания концентрации. Цель совершает спасбросок Интеллекта в конце каждого своего хода, завершая эффект на себе при успехе.",
    "source": "PHB"
