    "classes": [
      "bard",
      "wizard",
      "warlock"
    ],
    "description": "Вы нацеливаетесь на существо, о котором знаете, находящееся на том же плане существования. Вы или добровольное существо, которого вы касаетесь, погружаетесь в состояние транса, чтобы выступить в роли вестника снов. Находясь в трансе, вестник становится недееспособным и имеет скорость 0.\n\nЕсли цель спит, то вестник появляется в снах цели и может общаться с ней, пока она остается в состоянии сна, в течение длительности заклинания. Вестник также может изменять окружающую среду сна, создавая пейзажи, объекты и другие образы. Вестник может выйти из транса в любой момент, что завершит действие заклинания. Цель будет полностью помнить сон после пробуждения.\n\nЕсли цель бодрствует, когда вы накладываете заклинание, то вестник об этом узнает и может либо завершить транс (и заклинание), либо ждать, пока цель не уснет, после чего вестник войдет в её сны.\n\nВы можете сделать так, чтобы вестник выглядел устрашающим для цели. Если вы это делаете, то вестник может передать сообщение длиной не более 10 слов, после чего цель совершает спасбросок Мудрости. В случае провала, цель не получает пользы от своего отдыха и при пробуждении получает 3к6 психического урона.",
    "source": "PHB"
