    "isConcentration": true,
    "isRitual": false,
    "classes": [
      "wizard"
    ],
    "description": "Невидимая стена силы возникает в точке по вашему выбору в пределах дистанции. Стена может появиться в любой ориентации по вашему выбору: горизонтально, вертикально или под углом. Она может свободно висеть в воздухе или опираться на твердую поверхность. Вы можете сформировать её в виде полусферического купола или сферы радиусом до 10 футов, либо придать ей плоскую форму, состоящую из десяти панелей размером 10 на 10 футов. Каждая панель должна соприкасаться с другой. В любой форме стена имеет толщину 1/4 дюйма и существует в течение длительности заклинания. Если стена возникает в пространстве существа, то оно отталкивается на одну сторону стены (вы выбираете сторону).\n\nНичто не может физически пройти через стену. Она неуязвима ко всем видам урона и не может быть развеяна заклинанием Рассеивание магии [Dispel Magic] . Однако заклинание Распад [Disintegrate] мгновенно уничтожает стену. Стена также простирается на Эфирный план и блокирует эфирное перемещение через неё.",
