    "description": "Вы получаете способность двигать или манипулировать существами или предметами силой мысли. Когда вы накладываете это заклинание и действием магия на ваших следующих ходах до окончания длительности заклинания, вы можете направить свою волю на 1 существо или предмет, которое видите в пределах дистанции, вызывая один из эффектов, описанных ниже. Вы можете воздействовать на одну и ту же цель раунд за раундом или в любой момент выбрать новую. Если вы смените цель, то предыдущая перестанет быть под воздействием заклинания.\n\nСущество. Вы можете попытаться переместить существо огромного или меньшего размера. Цель должна совершить успешный спасбросок Силы, иначе вы перемещаете её на 30 футов в любом направлении в пределах дистанции заклинания. До конца вашего следующего хода существо получает состояние опутанный и если вы поднимете его в воздух, оно остаётся в подвешенном состоянии. Оно упадёт в конце вашего следующего хода, если вы не используете этот эффект снова и цель не провалит спасбросок.\n\nПредмет. Вы можете попытаться переместить предмет огромного или меньшего размера. Если предмет не надет и его не несёт существо, вы автоматически перемещаете его на 30 футов в любом направлении в пределах дистанции заклинания.\n\nЕсли предмет надет или его несёт существо, то это существо должно совершить успешный спасбросок Силы, иначе вы отбираете предмет и перемещаете его на 30 футов в любом направлении в пределах дистанции заклинания.\n\nВы можете осуществлять тонкий контроль над предметами с помощью телекинетической хватки, например, манипулировать простым инструментом, открывать дверь или контейнер, убирать или доставать предмет из открытого контейнера или выливать содержимое из склянки.",
