    "description": "Вы призываете парящий призрачный чёрный фонарь, который зависает над вами и излучает тусклый свет в радиусе 60 футов. Когда противник умирает в области этого тусклого света, частица души существа устремляется в фонарь. Фонарь может хранить количество частиц душ, равное модификатору вашей заклинательной характеристики. Эти частицы рассеиваются, когда заклинание оканчивается.\n\nБонусным действием вы можете израсходовать одну частицу души, чтобы создать один из следующих эффектов:\n\n• <strong>Вытягивание жизни.</strong> Частица души устремляется к выбранному вами существу, которое вы видите в пределах 60 футов от себя. Цель совершает спасбросок Телосложения, получая урон некротической энергией, равный <strong>4к8</strong> + модификатор вашей заклинательной характеристики, при провале или половину этого урона при успехе.\n• <strong>Восстановление нежити.</strong> Частица души влетает в выбранное вами существо-нежить, которое вы видите в пределах 60 футов от себя. Это существо восстанавливает количество хитов , равное <strong>4к8</strong> + модификатор вашей заклинательной характеристики.\n• <strong>Защита союзника.</strong> Частица души кружит вокруг выбранного вами существа, которое вы видите в пределах 60 футов от себя. До начала вашего следующего хода остальные существа совершают броски атаки по выбранному существу с помехой .",
