    "description": "Вы наполняете себя стихийной силой гениев. Вы получаете следующие преимущества, пока действует заклинание:\n\n• Стихийный иммунитет. Когда вы накладываете это заклинание, выберите один из следующих типов урона: кислотный, холодный, огненный, электрический или звуковой. Вы получаете сопротивление к выбранному типу урона.\n• Стихийный выброс. Когда вы накладываете это заклинание и в начале каждого вашего последующего хода, вы испускаете всплеск стихийной энергии в эманации радиусом 15 фт., исходящей от вас. Каждое выбранное вами существо в этой области совершает спасбросок Ловкости. При провале существо получает 2к6 урона кислотой, холодом, огнём, электричеством или звуком (на ваш выбор) и получает состояние лежащий ничком. При успешном спасброске существо получает половину урона.\n• Полёт. Вы получаете скорость полёта 30 фт. и можете парить.\n\nНаложение как заклинания круга. Если это заклинание накладывается как заклинание круга, его время накладывания увеличивается до 1 минуты, а длительность становится: концентрация, до 10 минут. За каждого вторичного заклинателя, участвующего в наложении, вы можете выбрать одно дополнительное существо (максимум девять). Эти существа также получают преимущества заклинания на время его действия.\n\nПри наложении заклинания каждый вторичный заклинатель должен потратить ячейку заклинаний 2-го уровня или выше, иначе заклинание не срабатывает.",
