    "description": "До окончания действия заклинания ваши вены вздуваются и становятся заметно зелёными под кожей, а из глаз постоянно текут жидкие яды. Вы получаете следующие преимущества:\n\n• Вы получаете иммунитет к урону ядом и состоянию отравленный.\n• Вы можете определять, имеют ли существа, которых вы видите в пределах 30 футов от себя, сопротивление к урону ядом, иммунитет к урону ядом или иммунитет к состоянию отравленный.\n• Бонусным действием выберите существо, которое видите в пределах 30 футов от себя. Это существо совершает спасбросок Телосложения против Сл ваших заклинаний. При провале существо теряет сопротивление к урону ядом, иммунитет к урону ядом или иммунитет к состоянию отравленный до конца вашего следующего хода.\n• Действием магия вы выпускаете линию яда длиной 15 футов и шириной 5 футов в выбранном направлении. Каждое существо в линии должно совершить спасбросок Телосложения. При провале существо получает 4к6 урона ядом и получает состояние отравленный до конца вашего следующего хода. При успехе существо получает только половину урона.",
