    "description": "Ваше тело впадает в кататоническое состояние, когда ваша душа покидает его и перемещается в контейнер, который вы использовали в качестве материального компонента заклинания. Пока ваша душа находится в контейнере, вы осознаёте своё окружение так, как если бы находились в пространстве контейнера. Вы не можете перемещаться или совершать реакции. Единственное действие, которое вы можете предпринять, это проецировать свою душу на расстояние до 100 футов от контейнера, чтобы вернуться в своё тело (окончив этим заклинание), либо попытаться сделать одержимым другого гуманоида.\n\nВы можете попытаться сделать другого видимого вами в пределах 100 футов от вас гуманоида одержимым вами. Существо, защищённое заклинанием Защита от зла и добра [Protection from Evil and Good] или Магический круг [Magic Circle], невозможно сделать одержимым. Цель совершает спасбросок Харизмы. При провале ваша душа входит в тело цели, а душа цели оказывается запертой в контейнере. В случае успешного спасброска цель сопротивляется вашим попыткам сделать её тело одержимым и вы не можете попытаться сделать это снова в течение 24 часов.\n\nКогда вы делаете тело существа одержимым вами, то вы управляете им. Ваши хиты, кость хитов, Сила, Ловкость, Телосложение, Скорость и чувства заменяются характеристиками существа. В остальном вы сохраняете свои игровые характеристики.\n\nТем временем душа одержимого существа может воспринимать окружающий мир из контейнера, используя свои собственные органы чувств, но не может двигаться и недееспособна.\n\nВо время одержимости телом вы можете совершить действие магия, чтобы вернуться из тела хозяина в контейнер, если он находится в пределах 100 футов от вас, возвращая душу существа в её тело. Если тело хозяина умирает, пока вы находитесь в нём, то существо умирает и вы совершаете спасбросок Харизмы против сложности вашего собственного заклинания. При успехе вы возвращаетесь в контейнер, если он находится в пределах 100 футов от вас. В противном случае вы умираете.\n\nЕсли контейнер уничтожен или заклинание заканчивается, то ваша душа возвращается в ваше тело. Если ваше тело находится на расстоянии более 100 футов от вас или если оно мертво, то вы умираете. Если душа другого существа находится в контейнере в момент его разрушения, то душа этого существа возвращается в её тело, если оно живо и находится в пределах 100 футов. В противном случае существо умирает.\n\nКогда заклинание заканчивается, контейнер уничтожается.",
