    "isRitual": true,
    "classes": [
      "wizard"
    ],
    "description": "Вы касаетесь сапфира, используемого при наложении заклинания, и объекта весом не более 10 фунтов, длина которого не превышает 6 футов. Заклинание оставляет невидимую метку на этом объекте и невидимое название предмета на сапфире. Каждый раз, когда вы накладываете это заклинание, вы должны использовать другой сапфир.\n\nПосле этого вы можете совершить действие магия, чтобы произнести имя объекта и раздавить сапфир. Объект мгновенно появляется у вас в руке, вне зависимости от расстояния и разделяющих планов, и заклинание прекращает действовать.\n\nЕсли другое существо держит или несет объект, то раздавливание сапфира не переносит его, но вместо этого вы узнаете, кто это существо и где оно сейчас находится.",
