    "isConcentration": false,
    "isRitual": false,
    "classes": [
      "wizard",
      "sorcerer"
    ],
    "description": "Ледяной шар летит от вас к точке по вашему выбору в пределах дистанции, где взрывается, образуя сферу радиусом 60 футов. Каждое существо в этой области должно совершить спасбросок Телосложения. При провале оно получает 10к6 урона холодом, при успехе половину этого урона.\n\nЕсли шар ударяется о водоём, то он замораживает воду на глубину до 6 дюймов и площадь квадрата со сторой 30 футов. Этот лёд сохраняется в течение 1 минуты. Существа, которые плавали на поверхности воды в момент замерзания, оказываются пойманными в ловушку и получают состояние опутанный . Существо в ловушке может действием совершить проверку Силы (Атлетика) против Сл. ваших заклинаний для высвобождения.\n\nВы можете воздержаться от запуска шара сразу после завершения наложения заклинания. Если вы так поступите, то в вашей руке появится шар размером со снаряд для пращи, холодный на ощупь. В любой момент вы или существо, которому вы передали шар, можете бросить его (на расстояние до 40 футов) или метнуть его с помощью пращи (на обычную дистанцию пращи). Он разбивается при ударе, вызывая тот же эффект, что и обычное наложение заклинания. Вы также можете просто положить шар, не разбивая его. Если шар не разобьётся в течение 1 минуты, то он взрывается.",
