    "description": "Вы выбираете существо и металлический предмет, который это существо держит или носит и который вы можете видеть в пределах дистанции. Существо совершает спасбросок Ловкости. При провале существо получает 5к8 урона огнём, а выбранный предмет плавится и растекается по земле, после чего возвращается к своей обычной форме и температуре. Если предмет магический, существо совершает спасбросок с преимуществом.\n\nЕсли существо пытается поднять предмет или иным образом касается его во время действия заклинания, предмет нагревается и плавится, а существо получает 5к8 урона огнём. Предмет возвращается в нормальное состояние, когда существо перестаёт касаться его или действие заклинания заканчивается.",
