    "description": "Вы призываете дух первобытного динозавра. Он появляется в свободном пространстве, которое вы видите в пределах дистанции, и использует блок характеристик Духа динозавра [Dinosaur Spirit] . Накладывая это заклинание, выберите анкилозавра, трицератопса или тираннозавра. Существо выглядит как динозавр выбранного вида, который определяет некоторые особенности в его блоке характеристик. Существо исчезает, когда его хиты опускаются до 0 или когда заклинание оканчивается.\n\nСущество является союзником для вас и ваших союзников. В бою оно имеет ту же инициативу, что и вы, но совершает свой ход сразу после вашего. Оно подчиняется вашим устным командам (действие от вас не требуется). Если вы не отдаёте ему команд, оно совершает действие уклонение и использует своё перемещение, чтобы избегать опасности.",
    "source": "PHB",
    "higherLevels": "Для определения уровня заклинания в блоке характеристик используйте уровень затраченной ячейки."
