    "isConcentration": false,
    "isRitual": false,
    "classes": [],
    "description": "Это заклинание проклинает существо ужасным старением. Цель должна совершить спасбросок Силы.\n\nУспешный спасбросок. При успехе цель получает 2к10 урона некротической энергией и осознаёт, что стала целью проклятия. В течение 1 минуты цель получает уязвимость к дробящему, колющему или рубящему урону (на ваш выбор при накладывании заклинания).\n\nНачальный эффект. При провале цель получает 6к10 урона некротической энергией и оказывается проклята.\n\nСрабатывающее событие. В следующий раз, когда цель завершает продолжительный отдых, она обнаруживает у себя новые морщины, седые волосы или пятна, которых раньше не было, и проклятие переходит к стадии 1.\n\nСтадия 1. Проклятое существо стремится отдыхать при любой возможности, становясь вялым и ленивым.\n\nСтадия 2. Проклятое существо становится немощным. После завершения короткого отдыха существо может использовать только 25 процентов своих костей хитов, округляя вверх, чтобы восстановить хиты.\n\nСтадия 3. Проклятое существо начинает стремительно стареть, становясь дряхлым. Оно совершает спасброски Силы, Ловкости и Телосложения с помехой.\n\nКульминация. Проклятое существо превращается в уродливую искривлённую фигуру и становится Похитителем тел.",
