    "classes": [],
    "description": "Это заклинание проклинает существо неконтролируемым нравом и жаждой насилия. Цель должна совершить спасбросок Мудрости.\n\nУспешный спасбросок. При успехе цель получает 4к10 урона психической энергией и осознаёт, что стала целью проклятия.\n\nКроме того, в течение 1 минуты цель совершает атаки, выполняемые с помощью реакций, с помехой.\n\nНачальный эффект. При провале цель получает 8к10 урона психической энергией и оказывается проклята.\n\nСрабатывающее событие. В следующий раз, когда проклятое существо атакует оружием или накладывает заклинание, используя фокусировку для заклинаний, старая рана вновь открывается, и проклятие переходит к стадии 1.\n\nСтадия 1. Проклятое существо становится легко раздражимым и агрессивным.\n\nСтадия 2. Проклятое существо становится одержимо насилием. Восторг одиночной битвы опьяняет его, а отношение к союзникам ухудшается по мере усиления проклятия. Проклятое существо не получает никаких преимуществ от своих коротких отдыхов.\n\nСтадия 3. Проклятое существо охватывает ненасытная жажда крови, и оно не способно отдыхать, пока остаются враги, которых можно убивать. Проклятое существо не получает никаких преимуществ от своих продолжительных отдыхов.\n\nКульминация. Проклятое существо превращается в уродливую искривлённую фигуру и становится Аватаром Резни.",
