    "description": "На время длительности заклинания ваши глаза становятся абсолютно чёрными. Одно существо по вашему выбору, находящееся в пределах 60 футов от вас и видимое вами, должно преуспеть в спасброске Мудрости, иначе оно будет подвержено одному из следующих эффектов по вашему выбору на длительность заклинания:\n\n• Сон. Цель получает состояние бессознательный. Цель просыпается, если получает урон или если другое существо использует действие, чтобы разбудить её.\n• Паника. Цель получает состояние испуганный. В каждый свой ход испуганная цель должна использовать действие рывок и двигаться от вас по самому безопасному и короткому доступному маршруту. Если цель перемещается на расстояние не менее 60 футов от вас и не видит вас, этот эффект заканчивается.\n• Слабость. Цель получает состояние отравленный.\n\nВ каждый из ваших ходов до окончания действия заклинания вы можете действием магически нацелиться на другое существо, но не можете нацелиться на существо повторно, если оно преуспело в спасброске против этого наложенного заклинания.",
