    "description": "Вы и до 5 согласных существ в пределах 5 футов от вас мгновенно перемещаетесь в ранее назначенное святилище. Вы и любые существа, которые телепортируются с вами, появляетесь на ближайшем незанятом пространстве к месту, которое вы указали при подготовке своего святилища (см. ниже). Если вы накладываете это заклинание, не подготовив сначала святилище, оно не оказывает никакого эффекта.\n\nВы должны назначить местоположение, например, храм, в качестве святилища, наложив это заклинание там.",
