    "description": "Вы можете накладывать это заклинание только ночью. Выберите до 3 трупов гуманоидов среднего или маленького размера в пределах дистанции. Все трупы становятся упырями под вашим контролем (см. статблок в Бестиарии).\n\nВ каждый свой ход вы можете бонусным действием мысленно приказать любому существу, оживлённому этим заклинанием, если оно находится в пределах 120 футов от вас (если вы контролируете несколько существ, то вы можете отдавать один и тот же приказ любому количеству из них одновременно). Вы решаете, какое действие совершит это существо, и куда оно переместится в свой следующий ход, или вы можете отдать общий приказ, например, охранять конкретную комнату или коридор. Если вы не отдадите команду, то существо выполняет действие уклонение и перемещается только для того, чтобы избежать вреда. Получив приказ, существо продолжает его выполнять, пока задача не будет завершена.\n\nСущество находится под вашим контролем 24 часа, после чего перестаёт слушаться приказов. Для поддержания контроля ещё на 24 часа вы должны наложить это заклинание на него ещё раз до окончания 24-часового периода. Такое наложение заклинания только поддерживает контроль над уже созданными существами, количество которых не может быть больше 3, и не оживляет новых.",
