    "description": "Вы создаёте стену льда на твёрдой поверхности в пределах дистанции. Вы можете сформировать её в виде полусферического купола или сферы с радиусом до 10 футов, либо создать плоскую поверхность, состоящую из десяти панелей размером 10 на 10 футов. Каждая панель должна соприкасаться с другой. В любой форме стена имеет толщину 1 фут и существует в течение длительности заклинания.\n\nЕсли стена возникает в пространстве существа, то оно отталкивается на одну из сторон стены (вы выбираете сторону) и совершает спасбросок Ловкости. При провале существо получает 10к6 урона холодом, а при успехе половину этого урона.\n\nСтена является объектом, который можно повредить и тем самым пробить. У неё 12 КД и 30 хитов на каждую 10 футовую секцию. Она имеет иммунитет к урону холодом, ядом и психической энергией, а также уязвимость к урону огнём. Сведение 10 футовой секции стены к 0 хитам разрушает её и оставляет за собой слой холодного воздуха в том месте, где находилась стена.\n\nСущество, которое впервые за ход проходит через этот слой холодного воздуха, должно совершить спасбросок Телосложения, получая 5к6 урона холодом при провале или половину этого урона при успехе.",
