    "classes": [
      "druid"
    ],
    "description": "Вы создаёте стену переплетённых ветвей, покрытых острыми шипами. Стена появляется в пределах дистанции на твёрдой поверхности и существует на протяжении всего времени действия заклинания. Вы можете выбрать длину стены до 60 футов, высоту до 10 футов и толщину до 5 футов, либо создать круг диаметром до 20 футов, высотой до 20 футов и толщиной до 5 футов. Стена блокирует линию обзора.\n\nКогда стена появляется, каждое существо в её области совершает спасбросок Ловкости. При провале существо получает 7к8 колющего урона, при успехе половину этого урона.\n\nСущество может перемещаться через стену, но это происходит медленно и болезненно. На каждый фут, пройденный через стену, требуется потратить 4 фута скорости. Более того, первый раз, когда существо входит в область стены в свой ход или заканчивает там ход, оно совершает спасбросок Ловкости, получая 7к8 рубящего урона при провале или половину этого урона при успехе. Существо совершает этот спасбросок только 1 раз за ход.",
