    "level": 6,
    "school": "Ограждение",
    "castingTime": "1 час",
    "range": "Касание",
    "components": "В, С, М",
    "materialDesc": "серебряный жезл стоимостью 10+ зм",
    "duration": "24 часа",
    "isConcentration": false,
    "isRitual": false,
    "classes": [
      "bard",
      "wizard"
    ],
    "description": "Вы создаёте охранное заклинание, которое защищает до 2500 квадратных футов пола. Охраняемая область может быть до 20 футов в высоту, и вы можете придать ей форму одного квадрата 50 на 50 футов, 100 смежных квадратов по 5 футов или 25 смежных квадратов по 10 футов.\n\nПри накладывании этого заклинания вы можете указать тех, кто не будет подвержен его эффектам. Вы также можете задать пароль, который, если будет произнесён вслух в пределах 5 футов от охраняемой области, сделает говорящего невосприимчивым к её эффектам. Заклинание создаёт следующие эффекты в пределах охраняемой области.\n\nЗаклинание Рассеивание магии [Dispel Magic] не действует на само заклинание Стражи, но каждый из нижеперечисленных эффектов может быть рассеян. Если все 4 эффекта будут рассеяны, то заклинание Стражи прекращается. Если вы накладываете это заклинание каждый день в течение 365 дней на одну и ту же область, то заклинание будет действовать до тех пор, пока все его эффекты не будут рассеяны.\n\nКоридоры. Туман наполняет все охраняемые коридоры, делая их сильно заслонённой местностью. Кроме того, на каждом перекрёстке или разветвлении с выбором направления существует 50-процентный шанс, что существо, кроме вас, будет считать, что идёт в сторону, противоположную той, в которую она на самом деле идёт.\n\nДвери. Все двери в охраняемой области магически заперты, как если бы они были опечатаны заклинанием Волшебный замок [Arcane Lock]. Кроме того, вы можете скрыть до 10 дверей иллюзией, придавая им вид обычных участков стены.\n\nЛестницы. Лестницы в охраняемой области заполняются паутиной от верхней до нижней части, как в заклинании Паутина [Web]. Эти нити восстанавливаются через 10 минут, если они будут разрушены, пока действует заклинание Стражи.\n\nДругие эффекты заклинания. Выберите 1 из следующих магических эффектов в пределах охраняемой области:\n\n• Пляшущие огоньки [Dancing Lights] в 4 коридорах с простым повторяющимся движением огоньков, пока действует заклинание Стражи.\n• Волшебные уста [Magic Mouth] в 2 местах\n• Зловонное облако [Stinking Cloud] в 2 местах (пары восстанавливаются через 10 минут, если рассеяны, пока действует заклинание Стражи)\n• Порыв ветра [Gust of Wind] в 1 коридоре или комнате (ветер дует постоянно, пока действует заклинание Стражи)\n• Внушение [Suggestion] в 1 квадрате 5 на 5 футов; любое существо, которое входит в этот квадрат, получает внушение мысленно.",
    "source": "PHB"
