    "description": "Вы создаёте стену из клубящейся серой энергии, сотканной из психической боли утраты. Стена появляется в пределах дистанции на твёрдой поверхности и существует до окончания действия заклинания. Вы выбираете: либо стена длиной до 60 футов, высотой 10 футов и толщиной 5 футов, либо кольцевая стена диаметром 20 футов, высотой до 20 футов и толщиной 5 футов. Стена блокирует линию обзора.\n\nСтена испускает тусклый свет в радиусе 100 футов. Когда вы накладываете заклинание, вы и назначенные вами существа можете проходить сквозь стену и находиться рядом с ней без вреда. Если существо перемещается в пределах 20 футов от неё или начинает там свой ход, оно должно преуспеть в спасброске Харизмы, иначе получает состояние недееспособный до начала своего следующего хода.\n\nСущество может пройти сквозь стену, хотя эта попытка эмоционально истощает. В первый раз за ход, когда существо входит в стену или заканчивает там свой ход, оно должно преуспеть в спасброске Харизмы, иначе получает 1 уровень истощения.",
