    "description": "Утыканные шипами цепи с мясницкими крюками на концах вырываются из земли в точке, которую вы видите в пределах дистанции, хлеща всё вокруг в сфере радиусом 20 футов с центром в этой точке. Каждое существо в этой области совершает спасбросок Ловкости. При провале оно получает 8к6 колющего урона и получает состояние опутанный до окончания действия заклинания.\n\nКогда существо впервые входит в область цепей в свой ход или начинает там ход, оно должно преуспеть в спасброске Ловкости, иначе получит состояние опутанный, пока находится в области или пока не освободится.\n\nСущество, опутанное цепями, может действием совершить проверку Силы (Атлетика) против Сл ваших заклинаний. При успехе оно перестаёт быть опутанным.\n\nКогда существо, опутанное этим заклинанием, оканчивает свой ход, оно получает 3к6 дробящего урона.",
    "source": "PHB",
