    "description": "Вы вызываете дух с Верхних планов, который проявляется в виде столба света в цилиндре радиусом 10 футов и высотой 40 футов с центром на точке в пределах дистанции. Для каждого существа, которое вы видите в цилиндре, выберите, какой свет из указанных ниже освещает его:\n\n• Исцеляющий свет. Цель восстанавливает хиты в количестве, равном 4к12 плюс ваш модификатор характеристики заклинания.\n• Жгучий свет. Цель совершает спасбросок Ловкости, получая 6к12 урона излучением при провале или половину этого урона при успешном спасброске.\n\nПока заклинание активно, яркий свет наполняет цилиндр, и когда вы перемещаетесь в свой ход, то вы также можете переместить цилиндр на расстояние до 30 футов.\n\nКогда цилиндр перемещается в пространство существа, которое вы видите, или когда существо, которое вы видите, входит в цилиндр или заканчивает свой ход там, то вы можете осветить его одним из типов света. Существо может быть затронуто этим заклинанием только 1 раз за ход.",
    "source": "PHB",
    "higherLevels": "Восстановление хитов и урон увеличиваются на 1к12 за каждый уровень ячейки выше 7."
