    "description": "Вы пытаетесь превратить одно существо, которое видите в пределах дистанции, в дерево. Существо совершает спасбросок Телосложения. При провале оно получает состояние схваченное, поскольку его плоть начинает затвердевать, превращаясь в кору. При успехе его скорость становится равной 0 до начала вашего следующего хода.\n\nСущество, схваченное этим заклинанием, совершает спасбросок Телосложения в конце каждого своего хода. Если оно успешно проходит спасбросок три раза, состояние оканчивается. Если оно проваливает спасбросок три раза, оно превращается в дерево и получает состояние окаменевший. Успехи и провалы не обязаны быть последовательными; отслеживайте оба результата, пока цель не наберёт три одинаковых.\n\nЕсли существо будет сожжено, срублено или иным образом уничтожено, пока находится в состоянии окаменевшее, оно погибает.\n\nСущество остаётся преобразованным, если эффект не будет снят в течение 1 года при помощи Высшее восстановление [Greater Restoration], Исполнение желаний [Wish] или схожей магии. Если существо проводит 1 год и 1 день в облике дерева, преобразование становится постоянным, и ничто не сможет вернуть существо в его первоначальную форму.",
    "source": "PHB"
