    "description": "На время действия заклинания ваша внешность становится неземной и манящей. Одно выбранное вами существо , которое вы видите в пределах 60 футов, должно преуспеть в спасброске Харизмы, иначе оно получает состояние очарованный на время действия заклинания.\n\nБудучи очарованной , цель также получает состояние недееспособный . Если она находится дальше чем в 5 футах от вас, в свой ход она движется к вам по кратчайшему пути, стараясь оказаться в пределах 5 футов от вас. Если очарованное существо заканчивает свой ход в пределах 5 футов от вас, оно получает 4к8 урона психической энергией.\n\nДвигаясь к вам, цель не избегает провоцированных атак , однако перед тем, как войти в опасную область, способную причинить ей урон, например в лаву или яму, она повторяет спасбросок, оканчивая действие заклинания на себе при успехе.\n\nПока заклинание не окончится, в последующие ходы вы можете совершать действие магия , чтобы выбрать целью другое существо. Однако вы не можете снова выбрать существо, которое уже преуспело в спасброске против этого накладывания заклинания.",
