    "description": "Вы создаёте подобие 1 зверя или гуманоида, который находится в пределах 10 футов от вас на протяжении всего времени накладывания заклинания. Вы завершаете наложение, касаясь как существа, так и кучи льда или снега, которая равна по размеру этому существу, и куча превращается в подобие, который является существом. Он использует статблок оригинального существа на момент наложения, за исключением того, что он является конструктом, его максимальные хиты составляют половину от оригинала и он не может накладывать это заклинание.\n\nПодобие является дружественным по отношению к вам и существам, которых вы выбираете. Он подчиняется вашим командам и действует в ваш ход в бою. Подобие не может получать уровни и не может совершать короткие или продолжительные отдыхи.\n\nЕсли подобие получает урон, то единственный способ восстановить его хиты это отремонтировать его во время вашего продолжительного отдыха, в течение которого вы тратите компоненты стоимостью 100 зм за каждый восстанавливаемый хит.\n\nПодобие должен оставаться в пределах 5 футов от вас для ремонта. Подобие существует, пока его хиты не упадут до 0, после чего он превращается в снег и тает. Если вы снова накладываете это заклинание, то любое подобие, созданное вами ранее с помощью этого заклинания, мгновенно уничтожается.",
