    "description": "Слово силы: Калечение\n\nВы приказываете телу существа искривиться и деформироваться. Если у цели 125 хитов или меньше, она получает 8к10 урона некротической энергией и получает состояние лежащий ничком. В противном случае скорость цели становится равной 0 до начала вашего следующего хода. Цель совершает спасбросок Телосложения в конце каждого своего хода, оканчивая этот эффект при успехе.",
