    "description": "Вы вступаете в пограничные окрестности Эфирного плана, в которых он пересекается с вашим текущим планом. Вы остаётесь в Пограничном эфире, пока активно заклинание или пока вы не окончите его действием. Всё это время вы можете перемещаться в любом направлении. Если вы перемещаетесь вверх или вниз, то каждый фут перемещения стоит 1 дополнительный фут. Вы можете воспринимать план, который покинули, но он выглядит серым, и вы не можете видеть там ничего на расстоянии более 60 футов.\n\nНаходясь на Эфирном Плане, вы можете воздействовать и быть подвержены воздействию только существ, объектов и эффектов на этом плане. Существа, не находящиеся на Эфирном плане, не могут воспринимать вас и взаимодействовать с вами, если только у них нет особого умения или магии, позволяющей делать это.\n\nКогда заклинание заканчивается, вы возвращаетесь на план, который покинули, в точку, соответствующую вашему положению в Пограничном эфире. Если вы появляетесь в занятом пространстве, то вы смещаетесь в ближайшее незанятое пространство и получаете урон силовым полем, равный двойному количеству футов, на которое вы были перемещены.\n\nЭто заклинание мгновенно заканчивается, если вы сотворите его, находясь на Эфирном плане или на плане, который не граничит с ним, например, на одном из Внешних планов.",
    "source": "PHB",
    "higherLevels": "Вы можете нацелить до 3 добровольных существ (включая себя) за каждый уровень ячейки выше 7. Эти существа должны находиться в пределах 10 футов от вас в момент сотворения заклинания."
