    "description": "Когда вы накладываете это заклинание, то выберите, будет ли оно создавать антипатию или симпатию, и выберите 1 цель, которая является существом или объектом размером не больше огромного. Затем укажите вид существа, например, красных драконов, гоблинов или вампиров.\n\nСущество выбранного вида совершает спасбросок Мудрости, когда оказывается в пределах 120 футов от цели. Ваш выбор антипатии или симпатии определяет, что произойдёт с существом, если оно провалит этот спасбросок:\n\nАнтипатия. Существо получает состояние испуганный. Испуганное существо должно использовать своё перемещение в свой ход, чтобы как можно быстрее отдалиться от цели, двигаясь по самому безопасному маршруту.\n\nСимпатия. Существо получает состояние очарованный. Очарованное существо должно использовать своё перемещение в каждый свой ход, чтобы как можно ближе приблизиться к цели, двигаясь по самому безопасному маршруту. Если существо находится в пределах 5 футов от цели, то оно не может добровольно отойти от неё. Если цель наносит урон очарованному существу, то это существо может совершить спасбросок Мудрости, чтобы прекратить действие эффекта, как описано ниже.\n\nОкончание эффекта. Если испуганное или очарованное существо заканчивает свой ход на расстоянии более 120 футов от цели, то оно совершает спасбросок Мудрости. При успешном спасброске существо больше не подвержено воздействию цели. Существо, успешно прошедшее спасбросок против этого эффекта, становится невосприимчивым к нему на 1 минуту, после чего снова может подвергнуться воздействию.",
