    "description": "Вы контролируете погоду в пределах 5 миль вокруг вас на протяжении длительности заклинания. Чтобы наложить это заклинание, вы должны находиться на открытом воздухе, и оно заканчивается досрочно, если вы войдёте в помещение. Когда вы накладываете заклинание, вы изменяете текущие погодные условия, которые определяются Мастером. Вы можете изменить осадки, температуру и ветер. Для вступления новых условий в силу требуется 1к4 × 10 минут. Как только они вступают в силу, вы можете изменить условия снова. Когда заклинание заканчивается, погода постепенно возвращается к норме.\n\nКогда вы изменяете погодные условия, найдите текущее состояние в следующих таблицах и измените его на одну стадию вверх или вниз. При изменении ветра вы также можете изменить его направление.\n\n<table class=\"card-table\"><caption>Осадки</caption><thead><tr><th style=\"width: 14%; text-align: center;\">Сила</th><th style=\"text-align: left;\">Состояние</th></tr></thead><tbody><tr><td style=\"text-align: center;\">1</td><td style=\"text-align: left;\">Чистое небо</td></tr><tr><td style=\"text-align: center;\">2</td><td style=\"text-align: left;\">Небольшая облачность</td></tr><tr><td style=\"text-align: center;\">3</td><td style=\"text-align: left;\">Пасмурно или густой туман</td></tr><tr><td style=\"text-align: center;\">4</td><td style=\"text-align: left;\">Дождь, град или снег</td></tr><tr><td style=\"text-align: center;\">5</td><td style=\"text-align: left;\">Проливной дождь, сильный град или метель</td></tr></tbody></table>\n\n<table class=\"card-table\"><caption>Температура</caption><thead><tr><th style=\"width: 14%; text-align: center;\">Сила</th><th style=\"text-align: left;\">Состояние</th></tr></thead><tbody><tr><td style=\"text-align: center;\">1</td><td style=\"text-align: left;\">Невыносимая жара</td></tr><tr><td style=\"text-align: center;\">2</td><td style=\"text-align: left;\">Жара</td></tr><tr><td style=\"text-align: center;\">3</td><td style=\"text-align: left;\">Тепло</td></tr><tr><td style=\"text-align: center;\">4</td><td style=\"text-align: left;\">Прохлада</td></tr><tr><td style=\"text-align: center;\">5</td><td style=\"text-align: left;\">Холод</td></tr><tr><td style=\"text-align: center;\">6</td><td style=\"text-align: left;\">Арктическая стужа</td></tr></tbody></table>\n\n<table class=\"card-table\"><caption>Ветер</caption><thead><tr><th style=\"width: 14%; text-align: center;\">Сила</th><th style=\"text-align: left;\">Состояние</th></tr></thead><tbody><tr><td style=\"text-align: center;\">1</td><td style=\"text-align: left;\">Штиль</td></tr><tr><td style=\"text-align: center;\">2</td><td style=\"text-align: left;\">Умеренный ветер</td></tr><tr><td style=\"text-align: center;\">3</td><td style=\"text-align: left;\">Сильный ветер</td></tr><tr><td style=\"text-align: center;\">4</td><td style=\"text-align: left;\">Буря</td></tr><tr><td style=\"text-align: center;\">5</td><td style=\"text-align: left;\">Шторм</td></tr></tbody></table>",
