    "description": "Собирая нити теневой материи из Царства Теней, вы создаёте иллюзию огромного призрачного дракона в свободном пространстве, которое видите в пределах дистанции. Иллюзия существует, пока действует заклинание, и занимает своё пространство, словно существо. Благодаря использованной для её создания теневой материи иллюзия осязаема, однако обладает иммунитетом ко всему урону и состояниям.\n\nКогда иллюзия появляется, каждый враг, способный её видеть, совершает спасбросок Мудрости. При провале существо роняет всё, что держит, и получает состояние испуганный на время действия заклинания. Если существо, испуганное таким образом, заканчивает свой ход в пространстве, из которого иллюзия находится вне его линии обзора, оно повторяет спасбросок, оканчивая на себе это состояние при успехе.\n\nБонусным действием вы можете переместить иллюзию на расстояние до 60 футов. В любой момент этого перемещения вы можете заставить призрачного дракона выдохнуть поток энергии 60-футовым конусом . Каждое существо в конусе совершает спасбросок Интеллекта, получая 6к6 урона кислотой, холодом, огнём, молнией, некротической энергией или ядом (тип урона вы выбираете при создании дракона) при провале или половину этого урона при успехе.\n\nСущество, которое совершает действие изучение , чтобы исследовать дракона, при успешной проверке Интеллекта (Анализ ) против Сл. спасброска от ваших заклинаний определяет, что тот является иллюзией. Если существо распознаёт иллюзию, оно видит сквозь её образ и совершает с преимуществом спасброски, чтобы окончить вызванное ею состояние испуганный и сопротивляться её выдоху.",
