    "description": "Выберите труп или несколько трупов в пределах дистанции, эквивалентных по размеру существу, которое вы оживляете (Мастер определяет, сколько трупов требуется). Ваше заклинание наполняет цель мерзким подобием жизни, поднимая её как нежить. Вы можете выбрать, чтобы цель стала существом нежить с ПО 3 или ниже (игровые характеристики существа определяет Мастер).\n\nВ каждый свой ход вы можете бонусным действием мысленно приказать любому существу, созданному этим заклинанием, если оно находится в пределах 60 футов от вас. (Если вы контролируете несколько существ, вы можете приказать любому количеству из них одновременно, отдавая одинаковый приказ каждому.) Вы определяете, какое действие совершит существо и куда оно переместится в свой следующий ход, либо можете отдать общий приказ, например охранять определённую комнату или коридор. Если вы не отдаёте приказов, существо совершает действие уклонение. Получив приказ, существо продолжает следовать ему, пока задача не будет выполнена.\n\nСущество находится под вашим контролем 24 часа, после чего перестаёт подчиняться любым вашим приказам. Чтобы сохранить контроль над существом ещё на 24 часа, вы должны снова наложить это заклинание на существо до окончания текущего 24-часового периода. Такое применение заклинания подтверждает ваш контроль над 1 существом, которое вы оживили этим заклинанием, вместо оживления нового. Любое существо, которое вы поддерживали этим заклинанием 30 дней, остаётся под вашим постоянным контролем. Вы можете одновременно контролировать не более четырёх существ этим заклинанием.",
