    "description": "Выберите любое число согласных существ, которых видите в пределах дистанции. Вы превращаете каждую цель в зверя большого или меньше размера с показателем опасности не больше 4. Вы можете выбрать разных зверей для каждой цели. В последующие ходы вы можете использовать действие магия , чтобы снова превратить цели.\n\nСтатблок цели заменяется статблоком зверя, но цель сохраняет свой тип существа; количество хитов; кость хитов; мировоззрение; способность говорить; а также значения Интеллекта, Мудрости и Харизмы. Действия цели ограничены анатомией формы зверя и она не может накладывать заклинания. Снаряжение цели сливается с новой формой и цель не может использовать это снаряжение, находясь в этой форме.\n\nЦель получает количество временные хиты/url:temporary-hit-points-phb, равное количеству хитов первой формы, в которую цель превратилась. Эти временные хиты исчезают, если какие-либо временные хиты остаются к моменту окончания действия заклинания. Превращение длится в течение времени действия заклинания или пока цель не выйдет из этой формы бонусным действием\n\nизменено Эрратой",
