    "description": "Вы создаёте магическое взрывное семя внутри существа, которое видите в пределах дистанции. Цель совершает спасбросок Телосложения, получая 10к10 урона огнём при провале или половину этого урона при успехе.\n\nЗатем от цели исходит взрыв. Каждое существо в пределах 60-футовой эманации , исходящей от цели (за исключением самой цели), совершает спасбросок Ловкости с помехой , если это заклинание опустило количество хитов цели до 0. При провале существо получает 10к10 урона огнём, а при успехе — половину этого урона.\n\nНемагический предмет, который никто не носит и не держит, также получает этот урон, если находится в пределах эманации. Если предмет способен гореть, он воспламеняется .",
