    "isConcentration": false,
    "isRitual": false,
    "classes": [
      "wizard",
      "warlock"
    ],
    "description": "Вы создаёте магическое ограничение, чтобы удержать существо, которое вы видите в пределах дистанции. Цель должна сделать спасбросок Мудрости. При успешном спасброске цель не подвергается воздействию заклинания и становится невосприимчивой к этому заклинанию на следующие 24 часа. При неудачном спасброске цель заключена в заточении. Пока она заключена, цель не нуждается в дыхании, пище или воде, и не стареет. Заклинания прорицания не могут обнаружить или воспринять заключённую цель, и цель не может телепортироваться. До окончания действия заклинания цель также подвергается 1 из следующих эффектов по вашему выбору:\n\n• Захоронение. Цель погребена под землёй в полой сфере магической силы, достаточно большой, чтобы вместить цель. Ничто не может проникнуть внутрь или выйти из сферы.\n• Сковывание. Цепи, прочно закреплённые в земле, удерживают цель на месте. Цель получает состояние опутанный и не может быть перемещена никакими средствами.\n• Ограждённая тюрьма. Цель заперта в демиплане, защищённом от телепортации и перемещении между планами. Демиплан на ваш выбор: лабиринт, клетка, башня или подобное.\n• Миниатюризация. Цель уменьшается до 1 дюйма (2,5 сантиметра) в высоту и заперта внутри неразрушимого драгоценного камня или подобного объекта. Свет может проходить через драгоценный камень (позволяя цели видеть окружение и другим существам видеть цель), но ничто другое не может проникнуть сквозь него любыми средствами.\n• Оцепенение. Цель получает состояние бессознательный и не может быть разбужена.\n\nЗавершение заклинания. Когда вы накладываете заклинание, укажите условие, которое завершит его. Условие может быть как простым, так и сложным по вашему выбору, но Мастер должен согласиться, что оно имеет высокую вероятность наступления в течение следующего десятилетия. Условие должно быть наблюдаемым действием, таким как выполнение кем-либо определённого предложения в храме вашего бога, спасение вашей истинной любви или победа над конкретным монстром.\n\nЗаклинание Рассеивание магии [Dispel Magic] может прекратить действие этого заклинания только если оно накладывается ячейкой 9 уровня и нацелено либо на тюрьму, либо на компонент, использованный для её создания.",
