    "duration": "Мгновенно",
    "isConcentration": false,
    "isRitual": false,
    "classes": [
      "druid",
      "cleric"
    ],
    "description": "Вы касаетесь мёртвого существа, которое умерло не более 200 лет назад и не скончалось от старости.\n\nСущество возвращается к жизни с полным количеством хитов. Это заклинание также нейтрализует любые яды, лечит все магические болезни и снимает все проклятия, наложенные на существо в момент смерти. Заклинание закрывает все смертельные раны, восстанавливает любые утраченные части тела и повреждённые органы. Если существо было нежитью, то оно возвращается в свою не-нежить форму.\n\nЗаклинание может создать новое тело, если оригинальное больше не существует. В этом случае вы должны произнести имя существа. Существо появляется в свободном месте на расстоянии до 10 футов от вас.",
