    "description": "Вы создаёте разлом между планами в форме клинка длиной около 3 футов, который существует всё время действия заклинания. Разлом появляется в пределах дистанции в выбранной вами точке, и вы можете немедленно совершить до двух рукопашных атак заклинанием, каждая из которых нацелена на существо или объект в пределах 5 фт. от разлома.\n\nПри попадании цель получает 10к6 урона силовым полем. Эта атака считается критическим попаданием , если результат на к20 равен 18 или выше.\n\nБонусным действием в ваши последующие ходы вы можете переместить разлом на расстояние до 60 фт. и повторить две атаки против существа или объекта в пределах 5 фт. от него. Вы можете направить обе атаки в одну цель или в разные.\n\nКлинок может безвредно проходить сквозь любые преграды, включая те, что созданы заклинаниями вроде Стена силы [Wall of Force] .",
