    "description": "Огненные шары падают на землю в 4 различных точках, которые вы видите в пределах дистанции. Каждое существо в сфере радиусом 40 футов, центрированной на каждой из этих точек, совершает спасбросок Ловкости. Существо получает 20к6 урона огнём и 20к6 дробящего урона при провале или половину этого урона при успехе. Существо, находящееся в области действия нескольких огненных сфер, получает урон только 1 раз.\n\nНемагические объекты, которые не носят и не несут, также получают урон, если они находятся в области действия заклинания, и начинают гореть, если они воспламеняемые.",
