    "description": "В рамках накладывания этого заклинания вы должны потратить девять Костей Хитов, иначе заклинание автоматически проваливается. Бросьте Кости Хитов, потраченные на накладывание этого заклинания, и получите количество временных хитов, равное удвоенной сумме результата броска. Вы получаете тип существа цели заклинания в дополнение к собственному типу.\n\nПока действует заклинание, вы получаете иммунитет к состоянию отравленный; вам больше не нужно есть, пить или дышать; вы получаете сопротивление к дробящему, колющему и рубящему урону; а также получаете дополнительное преимущество в зависимости от вашего нового типа существа:\n\n• Небожитель. Вы получаете сопротивление к урону излучением и некротической энергией, а также скорость полёта 60 футов.\n• Элементаль. Вы получаете сопротивление к урону кислотой, холодом, огнём, электричеством и звуком.\n• Фея. Вы можете бонусным действием получить состояние невидимый до начала вашего следующего хода либо телепортироваться на расстояние до 60 футов в незанятое пространство, которое можете видеть.\n• Исчадие. Вы получаете сопротивление к урону холодом и огнём, а также скорость полёта 60 футов.\n• Нежить. Вы получаете иммунитет к урону некротической энергией, а также иммунитет к состояниям очарованный и испуганный.\n\nВы сохраняете тип существа и эти преимущества, пока вновь не наложите это заклинание или не будете опущены до 0 хитов.",
