    "description": "Вы высвобождаете силу своего разума, чтобы нанести удар по интеллекту до 10 видимых существ на ваш выбор в пределах дистанции. Существа с показателем Интеллекта 2 или ниже не подвергаются эффекту.\n\nКаждая цель должна совершить спасбросок Интеллекта. При провале цель получает 14к6 урона психической энергией и становится ошеломлённой. При успешном спасброске цель получает только половину урона.\n\nЕсли в результате этого урона хиты цели опускаются до 0, то её голова взрывается, если она у неё есть.\n\nВ конце каждого своего хода ошеломлённая цель повторяет спасбросок, прекращая состояние при успехе.",
