    "description": "Вы произносите священное слово и пересоздаёте существо, которое можете видеть, по образу архисерафов. Состояние отравленный на существе оканчивается, проклятия на цели подавляются на время действия заклинания, а её хиты восстанавливаются до максимума. Значения характеристик существа ниже 18 становятся равны 18. В зависимости от произнесённого слова вы также благословляете цель силой архисерафа, к которому взываете:\n\n• Афаэлон: Цель получает иммунитет к состоянию очарованный. Если цель проваливает спасбросок, она может совершить реакцию, чтобы перебросить этот спасбросок. Она обязана использовать новый результат.\n• Эмпиреус: Цель получает иммунитет к состоянию испуганный, а также наносит дополнительные 4к6 урона силовым полем первой цели, по которой попадает в каждый свой ход.\n• Миклас: Цель получает иммунитет к урону ядом и состоянию отравленный, а также восстанавливает 4к6 хитов в начале каждого своего хода.\n• Мораэль: Цель получает 30 временных хитов. Когда союзник в пределах 60 футов от цели получает урон, цель может совершить реакцию, чтобы получить этот урон вместо него.\n• Солима: Цель получает иммунитет к урону звуком. Когда цель получает урон от существа, которое может видеть, она может совершить реакцию, чтобы нанести этому существу урон огнём, равный вызвавшему эффект урону.\n• Забриэль: Цель получает истинное зрение в пределах 60 футов. В конце каждого своего хода цель может даровать героическое вдохновение союзнику, у которого его нет.",
